export const SPEAK_GROUPS = [["A","Giới thiệu, gia đình, bạn bè","👤"],["B","Du lịch","🧳"],["C","Ước mơ, công việc và Trung Quốc","🌟"],["D","Quê hương, ăn uống và học tập","🏡"],["E","Thi cử, hy vọng, ứng xử và kỷ niệm","🎓"],["F","Thể thao và sức khỏe","🏃"],["G","Kế hoạch và công việc tương lai","🗓️"],["H","Sở thích và quan điểm sống","☕"]];
export const SPEAK_ITEMS = [{"id":1,"q":"请介绍一下自己？","qvi":"Giới thiệu bản thân","s":[["我叫黎辉遵。","Tôi tên là Lê Huy Tuân.","Wǒ jiào Lí Huī Zūn."],["我今年二十五岁。","Năm nay tôi 25 tuổi.","Wǒ jīnnián èrshíwǔ suì."],["我是越南人。","Tôi là người Việt Nam.","Wǒ shì Yuènán rén."],["我家在乂安。","Nhà tôi ở Nghệ An.","Wǒ jiā zài Yì'ān."],["我家有五口人。","Gia đình tôi có năm người.","Wǒ jiā yǒu wǔ kǒu rén."],["我很喜欢我的家。","Tôi rất yêu gia đình mình.","Wǒ hěn xǐhuan wǒ de jiā."],["我以前在莫斯科学习。","Trước đây tôi học ở Moscow.","Wǒ yǐqián zài Mòsīkē xuéxí."],["现在我在汉语中心学习汉语。","Hiện tại tôi học tiếng Trung ở trung tâm.","Xiànzài wǒ zài Hànyǔ zhōngxīn xuéxí Hànyǔ."],["我的汉语不太好。","Tiếng Trung của tôi chưa được tốt lắm.","Wǒ de Hànyǔ bú tài hǎo."],["我想说好汉语。","Tôi muốn nói tiếng Trung thật tốt.","Wǒ xiǎng shuō hǎo Hànyǔ."],["我喜欢看电影，也喜欢踢足球。","Tôi thích xem phim và đá bóng.","Wǒ xǐhuan kàn diànyǐng, yě xǐhuan tī zúqiú."],["我想去北京玩。","Tôi muốn đến Bắc Kinh chơi.","Wǒ xiǎng qù Běijīng wán."],["我也想在FIT公司工作。","Tôi cũng muốn làm việc tại công ty FIT.","Wǒ yě xiǎng zài FIT gōngsī gōngzuò."]],"g":"A"},{"id":2,"q":"请介绍你最爱的人。","qvi":"Giới thiệu người bạn yêu quý nhất","s":[["我最爱的人是我的妈妈。","Người tôi yêu quý nhất là mẹ.","Wǒ zuì ài de rén shì wǒ de māma."],["我的妈妈今年五十五岁。","Mẹ tôi năm nay 55 tuổi.","Wǒ de māma jīnnián wǔshíwǔ suì."],["她是一个很好的人。","Mẹ là một người rất tốt.","Tā shì yí ge hěn hǎo de rén."],["她很爱我，我也很爱她。","Mẹ rất yêu tôi và tôi cũng rất yêu mẹ.","Tā hěn ài wǒ, wǒ yě hěn ài tā."],["妈妈很喜欢做饭。","Mẹ rất thích nấu ăn.","Māma hěn xǐhuan zuòfàn."],["她做的菜很好吃。","Những món mẹ nấu rất ngon.","Tā zuò de cài hěn hǎochī."],["我很喜欢吃妈妈做的菜。","Tôi rất thích ăn các món mẹ nấu.","Wǒ hěn xǐhuan chī māma zuò de cài."],["我每天和妈妈一起吃饭。","Mỗi ngày tôi ăn cơm cùng mẹ.","Wǒ měitiān hé māma yìqǐ chīfàn."],["吃饭的时候，我和妈妈说话。","Khi ăn cơm, tôi trò chuyện với mẹ.","Chīfàn de shíhou, wǒ hé māma shuōhuà."],["妈妈问我：“你今天怎么样？”","Mẹ hỏi: “Hôm nay con thế nào?”","Māma wèn wǒ: “Nǐ jīntiān zěnmeyàng?”"],["我说：“很好。”","Tôi đáp: “Rất tốt ạ.”","Wǒ shuō: “Hěn hǎo.”"],["妈妈听了也很高兴。","Nghe vậy mẹ cũng rất vui.","Māma tīng le yě hěn gāoxìng."],["晚上我们一起看电视。","Buổi tối chúng tôi cùng xem tivi.","Wǎnshang wǒmen yìqǐ kàn diànshì."],["我喜欢和妈妈在一起。","Tôi thích ở bên mẹ.","Wǒ xǐhuan hé māma zài yìqǐ."],["我希望妈妈每天都很高兴。","Tôi mong mẹ ngày nào cũng vui.","Wǒ xīwàng māma měitiān dōu hěn gāoxìng."]],"g":"A"},{"id":3,"q":"请介绍一下你的老师。","qvi":"Giới thiệu giáo viên của bạn","s":[["我有一个汉语老师。","Tôi có một giáo viên tiếng Trung.","Wǒ yǒu yí ge Hànyǔ lǎoshī."],["我的老师会说汉语。","Giáo viên của tôi biết nói tiếng Trung.","Wǒ de lǎoshī huì shuō Hànyǔ."],["老师每天都来学校。","Ngày nào giáo viên cũng đến trường.","Lǎoshī měitiān dōu lái xuéxiào."],["老师上午八点上课。","Giáo viên bắt đầu dạy lúc 8 giờ sáng.","Lǎoshī shàngwǔ bā diǎn shàngkè."],["老师说汉语说得很好。","Giáo viên nói tiếng Trung rất tốt.","Lǎoshī shuō Hànyǔ shuō de hěn hǎo."],["上课的时候，我听老师说汉语。","Trong giờ học, tôi nghe giáo viên nói tiếng Trung.","Shàngkè de shíhou, wǒ tīng lǎoshī shuō Hànyǔ."],["老师也教我们写汉字。","Giáo viên cũng dạy chúng tôi viết chữ Hán.","Lǎoshī yě jiāo wǒmen xiě Hànzì."],["有问题的时候，我会问老师。","Khi có câu hỏi, tôi sẽ hỏi giáo viên.","Yǒu wèntí de shíhou, wǒ huì wèn lǎoshī."],["老师会帮助我。","Giáo viên sẽ giúp đỡ tôi.","Lǎoshī huì bāngzhù wǒ."],["我觉得老师很好。","Tôi cảm thấy giáo viên rất tốt.","Wǒ juéde lǎoshī hěn hǎo."],["我喜欢上老师的课。","Tôi thích học tiết của giáo viên.","Wǒ xǐhuan shàng lǎoshī de kè."],["我想好好学习汉语。","Tôi muốn học tiếng Trung thật tốt.","Wǒ xiǎng hǎohǎo xuéxí Hànyǔ."]],"g":"A"},{"id":4,"q":"请介绍一下你的朋友。","qvi":"Giới thiệu một người bạn của bạn","s":[["我有一个好朋友。","Tôi có một người bạn tốt.","Wǒ yǒu yí ge hǎo péngyou."],["他是我以前的同学。","Bạn ấy là bạn học cũ của tôi.","Tā shì wǒ yǐqián de tóngxué."],["我们在一个学校学习。","Chúng tôi từng học cùng một trường.","Wǒmen zài yí ge xuéxiào xuéxí."],["他今年二十五岁。","Bạn ấy năm nay 25 tuổi.","Tā jīnnián èrshíwǔ suì."],["他很喜欢踢足球。","Bạn ấy rất thích đá bóng.","Tā hěn xǐhuan tī zúqiú."],["我也很喜欢踢足球。","Tôi cũng rất thích đá bóng.","Wǒ yě hěn xǐhuan tī zúqiú."],["星期天，我们一起踢足球。","Chủ nhật chúng tôi đá bóng cùng nhau.","Xīngqītiān, wǒmen yìqǐ tī zúqiú."],["踢足球以后，我们去喝水。","Sau khi đá bóng, chúng tôi đi uống nước.","Tī zúqiú yǐhòu, wǒmen qù hē shuǐ."],["现在我们不常见面。","Hiện tại chúng tôi không thường gặp nhau.","Xiànzài wǒmen bù cháng jiànmiàn."],["但是我们常常打电话。","Nhưng chúng tôi thường gọi điện thoại.","Dànshì wǒmen chángcháng dǎ diànhuà."],["他对我很好。","Bạn ấy đối xử với tôi rất tốt.","Tā duì wǒ hěn hǎo."],["我很喜欢这个朋友。","Tôi rất quý người bạn này.","Wǒ hěn xǐhuan zhè ge péngyou."]],"g":"A"},{"id":5,"q":"你觉得什么样的朋友是一个好朋友？","qvi":"Thế nào là một người bạn tốt?","s":[["我有两个好朋友。","Tôi có hai người bạn thân.","Wǒ yǒu liǎng ge hǎo péngyou."],["他们是我以前的同学。","Họ là bạn học cũ của tôi.","Tāmen shì wǒ yǐqián de tóngxué."],["我很喜欢他们。","Tôi rất quý họ.","Wǒ hěn xǐhuan tāmen."],["他们也很喜欢我。","Họ cũng rất quý tôi.","Tāmen yě hěn xǐhuan wǒ."],["我们都喜欢踢足球。","Chúng tôi đều thích đá bóng.","Wǒmen dōu xǐhuan tī zúqiú."],["星期天，我们一起踢足球。","Chủ nhật chúng tôi đá bóng cùng nhau.","Xīngqītiān, wǒmen yìqǐ tī zúqiú."],["我们也喜欢一起看电影。","Chúng tôi cũng thích xem phim cùng nhau.","Wǒmen yě xǐhuan yìqǐ kàn diànyǐng."],["有时候，我们一起吃饭。","Đôi khi chúng tôi ăn cơm cùng nhau.","Yǒu shíhou, wǒmen yìqǐ chīfàn."],["我的朋友喜欢和我说话。","Bạn bè tôi thích trò chuyện với tôi.","Wǒ de péngyou xǐhuan hé wǒ shuōhuà."],["我也很喜欢听他们说话。","Tôi cũng thích lắng nghe họ.","Wǒ yě hěn xǐhuan tīng tāmen shuōhuà."],["我不高兴的时候，也会和他们说话。","Khi không vui, tôi cũng tâm sự với họ.","Wǒ bù gāoxìng de shíhou, yě huì hé tāmen shuōhuà."],["他们不高兴的时候，我和他们一起玩。","Khi họ không vui, tôi đi chơi cùng họ.","Tāmen bù gāoxìng de shíhou, wǒ hé tāmen yìqǐ wán."],["现在我们都很忙，但是常常打电话。","Bây giờ chúng tôi đều bận nhưng vẫn thường gọi điện.","Xiànzài wǒmen dōu hěn máng, dànshì chángcháng dǎ diànhuà."],["我很喜欢我的朋友。","Tôi rất quý bạn bè.","Wǒ hěn xǐhuan wǒ de péngyou."],["我想和他们一直做好朋友。","Tôi muốn mãi là bạn tốt của họ.","Wǒ xiǎng hé tāmen yìzhí zuò hǎo péngyou."]],"g":"A"},{"id":6,"q":"你常跟朋友一起做什么？请说一下。","qvi":"Bạn thường làm gì cùng bạn bè?","s":[["我有两个好朋友。","Tôi có hai người bạn thân.","Wǒ yǒu liǎng ge hǎo péngyou."],["他们都是我以前的同学。","Họ đều là bạn học cũ của tôi.","Tāmen dōu shì wǒ yǐqián de tóngxué."],["我们在一个学校学习。","Chúng tôi đã học cùng một trường.","Wǒmen zài yí ge xuéxiào xuéxí."],["现在我们都很忙。","Bây giờ chúng tôi đều rất bận.","Xiànzài wǒmen dōu hěn máng."],["我每天学习汉语，他们也有工作。","Mỗi ngày tôi học tiếng Trung, còn họ đi làm.","Wǒ měitiān xuéxí Hànyǔ, tāmen yě yǒu gōngzuò."],["我们不常一起玩。","Chúng tôi không thường đi chơi cùng nhau.","Wǒmen bù cháng yìqǐ wán."],["但是我们常常打电话。","Nhưng chúng tôi thường gọi điện.","Dànshì wǒmen chángcháng dǎ diànhuà."],["打电话的时候，我们说很多话。","Khi gọi điện, chúng tôi nói rất nhiều chuyện.","Dǎ diànhuà de shíhou, wǒmen shuō hěn duō huà."],["星期六和星期天，我们有时候一起踢足球。","Cuối tuần đôi khi chúng tôi đá bóng cùng nhau.","Xīngqīliù hé xīngqītiān, wǒmen yǒu shíhou yìqǐ tī zúqiú."],["我们都很喜欢足球。","Chúng tôi đều rất thích bóng đá.","Wǒmen dōu hěn xǐhuan zúqiú."],["踢足球以后，我们一起去喝咖啡。","Sau khi đá bóng, chúng tôi cùng đi uống cà phê.","Tī zúqiú yǐhòu, wǒmen yìqǐ qù hē kāfēi."],["我们也喜欢一起看电影。","Chúng tôi cũng thích cùng xem phim.","Wǒmen yě xǐhuan yìqǐ kàn diànyǐng."],["和他们在一起，我很高兴。","Ở bên họ tôi cảm thấy rất vui.","Hé tāmen zài yìqǐ, wǒ hěn gāoxìng."],["我很喜欢我的两个朋友。","Tôi rất quý hai người bạn này.","Wǒ hěn xǐhuan wǒ de liǎng ge péngyou."],["我想常常和他们在一起。","Tôi muốn thường xuyên gặp gỡ họ.","Wǒ xiǎng chángcháng hé tāmen zài yìqǐ."]],"g":"A"},{"id":7,"q":"你喜欢去哪里旅游？为什么？","qvi":"Bạn thích đi du lịch ở đâu? Tại sao?","s":[["我很喜欢旅游。","Tôi rất thích đi du lịch.","Wǒ hěn xǐhuan lǚyóu."],["我想去中国旅游。","Tôi muốn đi du lịch Trung Quốc.","Wǒ xiǎng qù Zhōngguó lǚyóu."],["我最想去北京。","Tôi muốn đến Bắc Kinh nhất.","Wǒ zuì xiǎng qù Běijīng."],["北京是一个很大的城市。","Bắc Kinh là một thành phố rất lớn.","Běijīng shì yí ge hěn dà de chéngshì."],["我想看看北京的学校。","Tôi muốn xem các trường học ở Bắc Kinh.","Wǒ xiǎng kànkan Běijīng de xuéxiào."],["我也想吃中国菜。","Tôi cũng muốn ăn món Trung Quốc.","Wǒ yě xiǎng chī Zhōngguó cài."],["我很喜欢吃面条和米饭。","Tôi rất thích ăn mì và cơm.","Wǒ hěn xǐhuan chī miàntiáo hé mǐfàn."],["我想和朋友一起去。","Tôi muốn đi cùng bạn bè.","Wǒ xiǎng hé péngyou yìqǐ qù."],["我们可以一起看电影。","Chúng tôi có thể cùng xem phim.","Wǒmen kěyǐ yìqǐ kàn diànyǐng."],["我们也可以一起照相。","Chúng tôi cũng có thể cùng chụp ảnh.","Wǒmen yě kěyǐ yìqǐ zhàoxiàng."],["我现在每天学习汉语。","Bây giờ tôi học tiếng Trung mỗi ngày.","Wǒ xiànzài měitiān xuéxí Hànyǔ."],["我想在中国说汉语。","Tôi muốn nói tiếng Trung ở Trung Quốc.","Wǒ xiǎng zài Zhōngguó shuō Hànyǔ."]],"g":"B"},{"id":8,"q":"你喜欢坐飞机还是火车去旅游？为什么？","qvi":"Bạn thích đi máy bay hay tàu hỏa khi du lịch?","s":[["我很喜欢去旅游。","Tôi rất thích đi du lịch.","Wǒ hěn xǐhuan qù lǚyóu."],["去旅游的时候，我喜欢坐飞机。","Khi du lịch, tôi thích đi máy bay.","Qù lǚyóu de shíhou, wǒ xǐhuan zuò fēijī."],["因为坐飞机很快。","Bởi vì đi máy bay rất nhanh.","Yīnwèi zuò fēijī hěn kuài."],["我想去很远的地方玩。","Tôi muốn đến những nơi rất xa để chơi.","Wǒ xiǎng qù hěn yuǎn de dìfang wán."],["坐飞机去很方便。","Đi máy bay rất tiện.","Zuò fēijī qù hěn fāngbiàn."],["我以前也坐过火车。","Trước đây tôi cũng từng đi tàu hỏa.","Wǒ yǐqián yě zuò guo huǒchē."],["坐火车可以看外面的山。","Đi tàu có thể nhìn núi bên ngoài.","Zuò huǒchē kěyǐ kàn wàimian de shān."],["我觉得坐火车也很好。","Tôi thấy đi tàu cũng rất tốt.","Wǒ juéde zuò huǒchē yě hěn hǎo."],["但是去北京的时候，我想坐飞机。","Nhưng khi đến Bắc Kinh, tôi muốn đi máy bay.","Dànshì qù Běijīng de shíhou, wǒ xiǎng zuò fēijī."],["我想和朋友一起去。","Tôi muốn đi cùng bạn bè.","Wǒ xiǎng hé péngyou yìqǐ qù."],["到了北京，我们一起吃饭。","Đến Bắc Kinh, chúng tôi cùng ăn cơm.","Dào le Běijīng, wǒmen yìqǐ chīfàn."],["我觉得这样很好。","Tôi nghĩ như vậy rất tốt.","Wǒ juéde zhèyàng hěn hǎo."]],"g":"B"},{"id":9,"q":"去旅游的时候，你要准备什么东西？","qvi":"Khi đi du lịch, bạn cần chuẩn bị gì?","s":[["我很喜欢旅游。","Tôi rất thích du lịch.","Wǒ hěn xǐhuan lǚyóu."],["下个月我想去北京玩。","Tháng sau tôi muốn đi Bắc Kinh chơi.","Xià ge yuè wǒ xiǎng qù Běijīng wán."],["去北京以前，我要准备一些东西。","Trước khi đi Bắc Kinh, tôi cần chuẩn bị vài thứ.","Qù Běijīng yǐqián, wǒ yào zhǔnbèi yìxiē dōngxi."],["我要带手机。","Tôi cần mang điện thoại.","Wǒ yào dài shǒujī."],["我也要带一些衣服。","Tôi cũng cần mang một ít quần áo.","Wǒ yě yào dài yìxiē yīfu."],["我要带钱和水。","Tôi cần mang tiền và nước.","Wǒ yào dài qián hé shuǐ."],["我还要带一本汉语书。","Tôi còn cần mang một cuốn sách tiếng Trung.","Wǒ hái yào dài yì běn Hànyǔ shū."],["坐飞机以前，我要早点儿去机场。","Trước khi đi máy bay, tôi cần đến sân bay sớm.","Zuò fēijī yǐqián, wǒ yào zǎo diǎnr qù jīchǎng."],["我想和朋友一起去。","Tôi muốn đi cùng bạn bè.","Wǒ xiǎng hé péngyou yìqǐ qù."],["我们到了北京就去吃饭。","Đến Bắc Kinh chúng tôi sẽ đi ăn.","Wǒmen dào le Běijīng jiù qù chīfàn."],["然后我们去看一看北京。","Sau đó chúng tôi đi tham quan Bắc Kinh.","Ránhòu wǒmen qù kàn yi kàn Běijīng."],["我想玩得很开心。","Tôi muốn có một chuyến đi thật vui.","Wǒ xiǎng wán de hěn kāixīn."]],"g":"B"},{"id":10,"q":"你的梦想是什么？请说一说。","qvi":"Ước mơ của bạn là gì?","s":[["我有一个梦想。","Tôi có một ước mơ.","Wǒ yǒu yí ge mèngxiǎng."],["我想说好汉语。","Tôi muốn nói tiếng Trung thật tốt.","Wǒ xiǎng shuō hǎo Hànyǔ."],["现在我每天学习汉语。","Bây giờ ngày nào tôi cũng học tiếng Trung.","Xiànzài wǒ měitiān xuéxí Hànyǔ."],["早上我去学校学习。","Buổi sáng tôi đến trường học.","Zǎoshang wǒ qù xuéxiào xuéxí."],["晚上我回家看书。","Buổi tối tôi về nhà đọc sách.","Wǎnshang wǒ huí jiā kàn shū."],["我也想去中国玩。","Tôi cũng muốn đi Trung Quốc chơi.","Wǒ yě xiǎng qù Zhōngguó wán."],["我最想去北京。","Tôi muốn đến Bắc Kinh nhất.","Wǒ zuì xiǎng qù Běijīng."],["到了北京，我想和中国朋友说话。","Đến Bắc Kinh, tôi muốn nói chuyện với bạn Trung Quốc.","Dào le Běijīng, wǒ xiǎng hé Zhōngguó péngyou shuōhuà."],["我还想找一个好工作。","Tôi còn muốn tìm một công việc tốt.","Wǒ hái xiǎng zhǎo yí ge hǎo gōngzuò."],["我想在FIT公司工作。","Tôi muốn làm việc ở công ty FIT.","Wǒ xiǎng zài FIT gōngsī gōngzuò."],["我想和家人一起生活。","Tôi muốn sống cùng gia đình.","Wǒ xiǎng hé jiārén yìqǐ shēnghuó."],["我想每天都很高兴。","Tôi muốn mỗi ngày đều vui vẻ.","Wǒ xiǎng měitiān dōu hěn gāoxìng."]],"g":"C"},{"id":11,"q":"为什么想进FIT公司工作？","qvi":"Tại sao bạn muốn làm ở FIT?","s":[["我很想去FIT公司工作。","Tôi rất muốn làm việc tại FIT.","Wǒ hěn xiǎng qù FIT gōngsī gōngzuò."],["FIT公司在乂安。","Công ty FIT ở Nghệ An.","FIT gōngsī zài Yì'ān."],["我的家也在乂安。","Nhà tôi cũng ở Nghệ An.","Wǒ de jiā yě zài Yì'ān."],["我很喜欢我的家乡。","Tôi rất yêu quê hương.","Wǒ hěn xǐhuan wǒ de jiāxiāng."],["我想在乂安工作。","Tôi muốn làm việc tại Nghệ An.","Wǒ xiǎng zài Yì'ān gōngzuò."],["我也很喜欢FIT公司。","Tôi cũng rất thích công ty FIT.","Wǒ yě hěn xǐhuan FIT gōngsī."],["我以前在莫斯科学习电脑。","Trước đây tôi học về máy tính tại Moscow.","Wǒ yǐqián zài Mòsīkē xuéxí diànnǎo."],["现在我学习汉语。","Bây giờ tôi học tiếng Trung.","Xiànzài wǒ xuéxí Hànyǔ."],["我会说一点儿汉语。","Tôi nói được một chút tiếng Trung.","Wǒ huì shuō yìdiǎnr Hànyǔ."],["我想说好汉语。","Tôi muốn nói tiếng Trung thật tốt.","Wǒ xiǎng shuō hǎo Hànyǔ."],["我想在公司说汉语。","Tôi muốn dùng tiếng Trung ở công ty.","Wǒ xiǎng zài gōngsī shuō Hànyǔ."],["我也想和大家一起工作。","Tôi cũng muốn làm việc cùng mọi người.","Wǒ yě xiǎng hé dàjiā yìqǐ gōngzuò."],["我想在公司认识很多朋友。","Tôi muốn quen nhiều bạn tại công ty.","Wǒ xiǎng zài gōngsī rènshi hěn duō péngyou."],["我喜欢工作，也喜欢学习。","Tôi thích làm việc và học tập.","Wǒ xǐhuan gōngzuò, yě xǐhuan xuéxí."],["我想在FIT公司好好工作。","Tôi muốn làm việc thật tốt tại FIT.","Wǒ xiǎng zài FIT gōngsī hǎohǎo gōngzuò."]],"note":"Đây là form phỏng vấn chung. Khi biết chính xác vị trí ứng tuyển, nên bổ sung lý do phù hợp với công việc của FIT thay vì chỉ nói những điểm chung.","g":"C"},{"id":12,"q":"在中国有哪里好玩？你想去中国哪里？","qvi":"Bạn muốn đi đâu chơi ở Trung Quốc?","s":[["我很想去中国玩。","Tôi rất muốn đi Trung Quốc chơi.","Wǒ hěn xiǎng qù Zhōngguó wán."],["中国有很多大城市。","Trung Quốc có nhiều thành phố lớn.","Zhōngguó yǒu hěn duō dà chéngshì."],["我最想去北京。","Tôi muốn đến Bắc Kinh nhất.","Wǒ zuì xiǎng qù Běijīng."],["北京是中国的一个大城市。","Bắc Kinh là một thành phố lớn của Trung Quốc.","Běijīng shì Zhōngguó de yí ge dà chéngshì."],["我想去北京看看。","Tôi muốn đến Bắc Kinh tham quan.","Wǒ xiǎng qù Běijīng kànkan."],["我想去天安门。","Tôi muốn đi Thiên An Môn.","Wǒ xiǎng qù Tiān'ānmén."],["我也想去长城。","Tôi cũng muốn đi Vạn Lý Trường Thành.","Wǒ yě xiǎng qù Chángchéng."],["我想和朋友一起照相。","Tôi muốn chụp ảnh cùng bạn bè.","Wǒ xiǎng hé péngyou yìqǐ zhàoxiàng."],["我们还可以吃北京的菜。","Chúng tôi còn có thể ăn món Bắc Kinh.","Wǒmen hái kěyǐ chī Běijīng de cài."],["我现在学习汉语。","Hiện tại tôi học tiếng Trung.","Wǒ xiànzài xuéxí Hànyǔ."],["我想在北京说汉语。","Tôi muốn nói tiếng Trung ở Bắc Kinh.","Wǒ xiǎng zài Běijīng shuō Hànyǔ."],["我觉得去北京玩很好。","Tôi nghĩ đi Bắc Kinh chơi rất vui.","Wǒ juéde qù Běijīng wán hěn hǎo."]],"g":"C"},{"id":13,"q":"你为什么想去中国留学？","qvi":"Tại sao bạn muốn du học Trung Quốc?","s":[["我很喜欢学习汉语。","Tôi rất thích học tiếng Trung.","Wǒ hěn xǐhuan xuéxí Hànyǔ."],["我想去中国学习。","Tôi muốn đến Trung Quốc học.","Wǒ xiǎng qù Zhōngguó xuéxí."],["我想在中国上学。","Tôi muốn đi học ở Trung Quốc.","Wǒ xiǎng zài Zhōngguó shàngxué."],["我也想认识中国朋友。","Tôi cũng muốn làm quen bạn Trung Quốc.","Wǒ yě xiǎng rènshi Zhōngguó péngyou."],["我现在会说一点儿汉语。","Bây giờ tôi nói được một chút tiếng Trung.","Wǒ xiànzài huì shuō yìdiǎnr Hànyǔ."],["我想说得更好。","Tôi muốn nói tốt hơn.","Wǒ xiǎng shuō de gèng hǎo."],["在中国，我可以每天说汉语。","Ở Trung Quốc, tôi có thể nói tiếng Trung mỗi ngày.","Zài Zhōngguó, wǒ kěyǐ měitiān shuō Hànyǔ."],["我还想看中国电影。","Tôi còn muốn xem phim Trung Quốc.","Wǒ hái xiǎng kàn Zhōngguó diànyǐng."],["我想吃中国菜。","Tôi muốn ăn món Trung Quốc.","Wǒ xiǎng chī Zhōngguó cài."],["放假的时候，我想去北京玩。","Khi nghỉ, tôi muốn đi Bắc Kinh chơi.","Fàngjià de shíhou, wǒ xiǎng qù Běijīng wán."],["学习以后，我想回越南工作。","Sau khi học xong, tôi muốn về Việt Nam làm việc.","Xuéxí yǐhòu, wǒ xiǎng huí Yuènán gōngzuò."],["我想用汉语和大家说话。","Tôi muốn dùng tiếng Trung nói chuyện với mọi người.","Wǒ xiǎng yòng Hànyǔ hé dàjiā shuōhuà."]],"g":"C"},{"id":14,"q":"请介绍你的老家。","qvi":"Giới thiệu quê hương","s":[["我的家在越南乂安。","Nhà tôi ở Nghệ An, Việt Nam.","Wǒ de jiā zài Yuènán Yì'ān."],["乂安是我的家乡。","Nghệ An là quê hương của tôi.","Yì'ān shì wǒ de jiāxiāng."],["我很喜欢我的家乡。","Tôi rất yêu quê hương.","Wǒ hěn xǐhuan wǒ de jiāxiāng."],["我的爸爸妈妈也住在这里。","Bố mẹ tôi cũng sống ở đây.","Wǒ de bàba māma yě zhù zài zhèlǐ."],["这里有山，也有海。","Ở đây có núi và có biển.","Zhèlǐ yǒu shān, yě yǒu hǎi."],["我觉得这里很漂亮。","Tôi thấy nơi đây rất đẹp.","Wǒ juéde zhèlǐ hěn piàoliang."],["这里的人也很好。","Con người ở đây cũng rất tốt.","Zhèlǐ de rén yě hěn hǎo."],["星期天，我喜欢和家人去海边玩。","Chủ nhật tôi thích đi biển cùng gia đình.","Xīngqītiān, wǒ xǐhuan hé jiārén qù hǎibiān wán."],["我们一起看海。","Chúng tôi cùng ngắm biển.","Wǒmen yìqǐ kàn hǎi."],["我很喜欢大海。","Tôi rất thích biển.","Wǒ hěn xǐhuan dàhǎi."],["我也喜欢这里的菜。","Tôi cũng thích món ăn ở đây.","Wǒ yě xǐhuan zhèlǐ de cài."],["这里有很多好吃的东西。","Ở đây có nhiều đồ ăn ngon.","Zhèlǐ yǒu hěn duō hǎochī de dōngxi."],["我想请我的朋友来乂安玩。","Tôi muốn mời bạn đến Nghệ An chơi.","Wǒ xiǎng qǐng wǒ de péngyou lái Yì'ān wán."],["我想和他们一起去看海。","Tôi muốn cùng họ đi ngắm biển.","Wǒ xiǎng hé tāmen yìqǐ qù kàn hǎi."],["我很爱我的家乡。","Tôi rất yêu quê hương.","Wǒ hěn ài wǒ de jiāxiāng."]],"g":"D"},{"id":15,"q":"你最喜欢哪一种菜？请说一说。","qvi":"Món ăn bạn thích nhất là gì?","s":[["我很喜欢吃越南菜。","Tôi rất thích ăn món Việt Nam.","Wǒ hěn xǐhuan chī Yuènán cài."],["我最喜欢妈妈做的菜。","Tôi thích món mẹ nấu nhất.","Wǒ zuì xǐhuan māma zuò de cài."],["妈妈每天都做饭。","Mẹ nấu ăn mỗi ngày.","Māma měitiān dōu zuòfàn."],["她做的菜很好吃。","Món mẹ nấu rất ngon.","Tā zuò de cài hěn hǎochī."],["我最喜欢吃鸡肉。","Tôi thích ăn thịt gà nhất.","Wǒ zuì xǐhuan chī jīròu."],["我也喜欢吃米饭。","Tôi cũng thích ăn cơm.","Wǒ yě xǐhuan chī mǐfàn."],["中午妈妈做鸡肉和米饭。","Buổi trưa mẹ làm thịt gà và cơm.","Zhōngwǔ māma zuò jīròu hé mǐfàn."],["我会和爸爸妈妈一起吃饭。","Tôi sẽ ăn cùng bố mẹ.","Wǒ huì hé bàba māma yìqǐ chīfàn."],["有时候我也帮妈妈做饭。","Đôi khi tôi cũng giúp mẹ nấu ăn.","Yǒu shíhou wǒ yě bāng māma zuòfàn."],["吃饭的时候，我们说很多话。","Khi ăn, chúng tôi nói nhiều chuyện.","Chīfàn de shíhou, wǒmen shuō hěn duō huà."],["我觉得和家人吃饭很好。","Tôi thấy ăn cơm cùng gia đình rất vui.","Wǒ juéde hé jiārén chīfàn hěn hǎo."],["我很喜欢妈妈做的饭。","Tôi rất thích cơm mẹ nấu.","Wǒ hěn xǐhuan māma zuò de fàn."]],"g":"D"},{"id":16,"q":"每天你学习汉语多长时间？学习方法是什么？","qvi":"Mỗi ngày bạn học tiếng Trung bao lâu, học thế nào?","s":[["我很喜欢学习汉语。","Tôi rất thích học tiếng Trung.","Wǒ hěn xǐhuan xuéxí Hànyǔ."],["我每天学习九个小时。","Mỗi ngày tôi học chín tiếng.","Wǒ měitiān xuéxí jiǔ ge xiǎoshí."],["早上八点，我去学校学习汉语。","Lúc 8 giờ sáng, tôi đến trường học tiếng Trung.","Zǎoshang bā diǎn, wǒ qù xuéxiào xuéxí Hànyǔ."],["上午十一点，我吃午饭。","Lúc 11 giờ trưa, tôi ăn cơm.","Shàngwǔ shíyī diǎn, wǒ chī wǔfàn."],["下午一点半，我又去学校学习汉语。","Lúc 1 giờ 30 chiều, tôi lại đến trường học tiếng Trung.","Xiàwǔ yì diǎn bàn, wǒ yòu qù xuéxiào xuéxí Hànyǔ."],["我和老师、同学一起学习。","Tôi học cùng giáo viên và bạn học.","Wǒ hé lǎoshī, tóngxué yìqǐ xuéxí."],["老师说汉语，我听老师说话。","Giáo viên nói tiếng Trung, tôi lắng nghe.","Lǎoshī shuō Hànyǔ, wǒ tīng lǎoshī shuōhuà."],["下午四点半，我回家。","Lúc 4 giờ 30 chiều, tôi về nhà.","Xiàwǔ sì diǎn bàn, wǒ huí jiā."],["晚上七点，我在家学习汉语。","Lúc 7 giờ tối, tôi học tiếng Trung ở nhà.","Wǎnshang qī diǎn, wǒ zài jiā xuéxí Hànyǔ."],["我写汉字，也读书。","Tôi viết chữ Hán và đọc sách.","Wǒ xiě Hànzì, yě dú shū."],["我还听汉语，练习说汉语。","Tôi còn luyện nghe và nói tiếng Trung.","Wǒ hái tīng Hànyǔ, liànxí shuō Hànyǔ."],["晚上十点，我不学习了。","Lúc 10 giờ tối, tôi ngừng học.","Wǎnshang shí diǎn, wǒ bù xuéxí le."],["我很喜欢汉语，也想说好汉语。","Tôi rất thích và muốn nói tốt tiếng Trung.","Wǒ hěn xǐhuan Hànyǔ, yě xiǎng shuō hǎo Hànyǔ."]],"g":"D"},{"id":17,"q":"你喜欢早上学习还是晚上学习？为什么？","qvi":"Bạn thích học buổi sáng hay buổi tối? Vì sao?","s":[["我每天都学习汉语。","Ngày nào tôi cũng học tiếng Trung.","Wǒ měitiān dōu xuéxí Hànyǔ."],["早上和晚上，我都学习。","Buổi sáng và buổi tối tôi đều học.","Zǎoshang hé wǎnshang, wǒ dōu xuéxí."],["我更喜欢早上学习。","Tôi thích học buổi sáng hơn.","Wǒ gèng xǐhuan zǎoshang xuéxí."],["我每天早上六点起床。","Mỗi sáng tôi thức dậy lúc 6 giờ.","Wǒ měitiān zǎoshang liù diǎn qǐchuáng."],["我先吃早饭，喝一点儿水。","Trước tiên tôi ăn sáng và uống chút nước.","Wǒ xiān chī zǎofàn, hē yìdiǎnr shuǐ."],["八点我去学校上课。","Lúc 8 giờ tôi đến trường học.","Bā diǎn wǒ qù xuéxiào shàngkè."],["早上我觉得很好。","Buổi sáng tôi cảm thấy rất khỏe khoắn.","Zǎoshang wǒ juéde hěn hǎo."],["我喜欢听老师说汉语。","Tôi thích nghe thầy cô nói tiếng Trung.","Wǒ xǐhuan tīng lǎoshī shuō Hànyǔ."],["下午我也学习汉语。","Buổi chiều tôi cũng học tiếng Trung.","Xiàwǔ wǒ yě xuéxí Hànyǔ."],["晚上我在家写汉字。","Buổi tối tôi ở nhà viết chữ Hán.","Wǎnshang wǒ zài jiā xiě Hànzì."],["有时候我有一点儿累。","Đôi lúc tôi hơi mệt.","Yǒu shíhou wǒ yǒu yìdiǎnr lèi."],["所以我喜欢早上学习。","Vì thế tôi thích học buổi sáng.","Suǒyǐ wǒ xǐhuan zǎoshang xuéxí."]],"g":"D"},{"id":18,"q":"你喜欢学汉语吗？你学汉语多久了？为什么学习汉语？","qvi":"Bạn có thích học tiếng Trung? Học bao lâu? Vì sao?","s":[["我很喜欢学习汉语。","Tôi rất thích học tiếng Trung.","Wǒ hěn xǐhuan xuéxí Hànyǔ."],["我现在在汉语中心学习。","Bây giờ tôi học ở trung tâm tiếng Trung.","Wǒ xiànzài zài Hànyǔ zhōngxīn xuéxí."],["我学汉语一个月了。","Tôi đã học tiếng Trung được một tháng.","Wǒ xué Hànyǔ yí ge yuè le."],["以前我也学过一点儿汉语。","Trước đây tôi đã từng học một chút tiếng Trung.","Yǐqián wǒ yě xué guo yìdiǎnr Hànyǔ."],["但是我很长时间没有说汉语了。","Nhưng lâu rồi tôi không nói tiếng Trung.","Dànshì wǒ hěn cháng shíjiān méiyǒu shuō Hànyǔ le."],["现在我又开始学习汉语。","Bây giờ tôi lại bắt đầu học tiếng Trung.","Xiànzài wǒ yòu kāishǐ xuéxí Hànyǔ."],["我每天都去中心学习。","Tôi đến trung tâm học mỗi ngày.","Wǒ měitiān dōu qù zhōngxīn xuéxí."],["老师很好，同学也很好。","Thầy cô tốt, bạn học cũng tốt.","Lǎoshī hěn hǎo, tóngxué yě hěn hǎo."],["我们一起读书，一起说汉语。","Chúng tôi cùng đọc sách và nói tiếng Trung.","Wǒmen yìqǐ dú shū, yìqǐ shuō Hànyǔ."],["晚上我回家写汉字。","Buổi tối tôi về nhà viết chữ Hán.","Wǎnshang wǒ huí jiā xiě Hànzì."],["我也听汉语、看中国电影。","Tôi cũng nghe tiếng Trung và xem phim Trung Quốc.","Wǒ yě tīng Hànyǔ, kàn Zhōngguó diànyǐng."],["我觉得汉语有一点儿难。","Tôi cảm thấy tiếng Trung hơi khó.","Wǒ juéde Hànyǔ yǒu yìdiǎnr nán."],["我想去中国玩。","Tôi muốn đến Trung Quốc chơi.","Wǒ xiǎng qù Zhōngguó wán."],["我也想用汉语工作。","Tôi cũng muốn dùng tiếng Trung để làm việc.","Wǒ yě xiǎng yòng Hànyǔ gōngzuò."],["我想说好汉语。","Tôi muốn nói tiếng Trung thật tốt.","Wǒ xiǎng shuō hǎo Hànyǔ."]],"g":"D"},{"id":19,"q":"考试前要准备什么？","qvi":"Cần chuẩn bị gì trước kỳ thi?","s":[["明天我有汉语考试。","Ngày mai tôi có bài thi tiếng Trung.","Míngtiān wǒ yǒu Hànyǔ kǎoshì."],["今天我在家学习汉语。","Hôm nay tôi học tiếng Trung ở nhà.","Jīntiān wǒ zài jiā xuéxí Hànyǔ."],["我看汉语书，也写汉字。","Tôi đọc sách tiếng Trung và viết chữ Hán.","Wǒ kàn Hànyǔ shū, yě xiě Hànzì."],["我还听汉语、说汉语。","Tôi còn nghe và nói tiếng Trung.","Wǒ hái tīng Hànyǔ, shuō Hànyǔ."],["有些汉字我不认识，我会问老师。","Có chữ Hán tôi không biết, tôi sẽ hỏi thầy cô.","Yǒuxiē Hànzì wǒ bú rènshi, wǒ huì wèn lǎoshī."],["老师说汉语，我听老师说话。","Thầy cô nói tiếng Trung, tôi lắng nghe.","Lǎoshī shuō Hànyǔ, wǒ tīng lǎoshī shuōhuà."],["我也和同学一起学习。","Tôi cũng học cùng bạn học.","Wǒ yě hé tóngxué yìqǐ xuéxí."],["下午我们一起看书，一起说汉语。","Buổi chiều chúng tôi cùng đọc sách, nói tiếng Trung.","Xiàwǔ wǒmen yìqǐ kàn shū, yìqǐ shuō Hànyǔ."],["晚上我在家看书。","Buổi tối tôi đọc sách ở nhà.","Wǎnshang wǒ zài jiā kàn shū."],["我不看电影，也不玩手机。","Tôi không xem phim, cũng không chơi điện thoại.","Wǒ bú kàn diànyǐng, yě bù wán shǒujī."],["晚上九点，我去睡觉。","Lúc 9 giờ tối tôi đi ngủ.","Wǎnshang jiǔ diǎn, wǒ qù shuìjiào."],["明天早上七点，我起床。","Sáng mai lúc 7 giờ tôi thức dậy.","Míngtiān zǎoshang qī diǎn, wǒ qǐchuáng."],["我吃早饭，也喝水。","Tôi ăn sáng và uống nước.","Wǒ chī zǎofàn, yě hē shuǐ."],["早上八点，我去学校考试。","Lúc 8 giờ tôi đến trường thi.","Zǎoshang bā diǎn, wǒ qù xuéxiào kǎoshì."],["我想明天的考试不太难。","Tôi mong bài thi ngày mai không quá khó.","Wǒ xiǎng míngtiān de kǎoshì bú tài nán."]],"g":"E"},{"id":20,"q":"你最大的希望是什么？","qvi":"Hy vọng lớn nhất của bạn là gì?","s":[["我有一个很大的希望。","Tôi có một hy vọng rất lớn.","Wǒ yǒu yí ge hěn dà de xīwàng."],["我希望我的家人都很好。","Tôi mong gia đình mình đều khỏe và ổn.","Wǒ xīwàng wǒ de jiārén dōu hěn hǎo."],["我爸爸妈妈现在在家。","Bố mẹ tôi hiện đang ở nhà.","Wǒ bàba māma xiànzài zài jiā."],["我想每天和他们一起吃饭。","Tôi muốn mỗi ngày ăn cơm cùng bố mẹ.","Wǒ xiǎng měitiān hé tāmen yìqǐ chīfàn."],["我也想说好汉语。","Tôi cũng muốn nói tốt tiếng Trung.","Wǒ yě xiǎng shuō hǎo Hànyǔ."],["现在我每天去中心学习。","Bây giờ ngày nào tôi cũng đến trung tâm học.","Xiànzài wǒ měitiān qù zhōngxīn xuéxí."],["我想去北京看看。","Tôi muốn đến Bắc Kinh tham quan.","Wǒ xiǎng qù Běijīng kànkan."],["我还想找一个好工作。","Tôi còn muốn tìm một công việc tốt.","Wǒ hái xiǎng zhǎo yí ge hǎo gōngzuò."],["我想在FIT公司工作。","Tôi muốn làm việc ở công ty FIT.","Wǒ xiǎng zài FIT gōngsī gōngzuò."],["有时间的时候，我想和朋友踢足球。","Khi có thời gian tôi muốn đá bóng với bạn.","Yǒu shíjiān de shíhou, wǒ xiǎng hé péngyou tī zúqiú."],["我想每天都很高兴。","Tôi muốn ngày nào cũng vui vẻ.","Wǒ xiǎng měitiān dōu hěn gāoxìng."],["这就是我最大的希望。","Đó là hy vọng lớn nhất của tôi.","Zhè jiù shì wǒ zuì dà de xīwàng."]],"g":"E"},{"id":21,"q":"如果朋友来你家做客，你会怎么欢迎他？","qvi":"Bạn sẽ đón tiếp thế nào khi có bạn đến nhà chơi?","s":[["我的朋友来我家玩，我很高兴。","Bạn đến nhà chơi, tôi rất vui.","Wǒ de péngyou lái wǒ jiā wán, wǒ hěn gāoxìng."],["我说：“你好！请坐！”","Tôi nói: “Chào bạn! Mời ngồi!”","Wǒ shuō: “Nǐ hǎo! Qǐng zuò!”"],["我请朋友进来坐。","Tôi mời bạn vào nhà ngồi.","Wǒ qǐng péngyou jìnlái zuò."],["我问他：“你想喝什么？”","Tôi hỏi: “Bạn muốn uống gì?”","Wǒ wèn tā: “Nǐ xiǎng hē shénme?”"],["他说：“我想喝茶。”","Bạn ấy nói: “Tôi muốn uống trà.”","Tā shuō: “Wǒ xiǎng hē chá.”"],["我请他喝茶。","Tôi mời bạn uống trà.","Wǒ qǐng tā hē chá."],["我也请他吃水果。","Tôi cũng mời bạn ăn hoa quả.","Wǒ yě qǐng tā chī shuǐguǒ."],["我的妈妈在家做饭。","Mẹ tôi ở nhà nấu cơm.","Wǒ de māma zài jiā zuòfàn."],["我和妈妈一起做菜。","Tôi cùng mẹ nấu ăn.","Wǒ hé māma yìqǐ zuò cài."],["中午我们一起吃饭。","Buổi trưa chúng tôi ăn cơm cùng nhau.","Zhōngwǔ wǒmen yìqǐ chīfàn."],["吃饭的时候，我们说很多话。","Khi ăn chúng tôi trò chuyện rất nhiều.","Chīfàn de shíhou, wǒmen shuō hěn duō huà."],["吃饭以后，我们一起看电视。","Sau khi ăn, chúng tôi cùng xem tivi.","Chīfàn yǐhòu, wǒmen yìqǐ kàn diànshì."],["下午我和朋友一起去海边玩。","Buổi chiều tôi đi biển chơi cùng bạn.","Xiàwǔ wǒ hé péngyou yìqǐ qù hǎibiān wán."],["朋友说：“这里很漂亮！”","Bạn nói: “Ở đây đẹp quá!”","Péngyou shuō: “Zhèlǐ hěn piàoliang!”"],["我听了很高兴。","Nghe vậy tôi rất vui.","Wǒ tīng le hěn gāoxìng."],["我想请他再来我家玩。","Tôi muốn mời bạn lại đến nhà chơi.","Wǒ xiǎng qǐng tā zài lái wǒ jiā wán."]],"g":"E"},{"id":22,"q":"你觉得什么样的孩子是一个好孩子？","qvi":"Theo bạn, thế nào là một người con ngoan?","s":[["我觉得好孩子很爱爸爸妈妈。","Tôi thấy con ngoan rất yêu bố mẹ.","Wǒ juéde hǎo háizi hěn ài bàba māma."],["好孩子会听爸爸妈妈的话。","Con ngoan sẽ nghe lời bố mẹ.","Hǎo háizi huì tīng bàba māma de huà."],["爸爸妈妈说话的时候，他会听。","Khi bố mẹ nói, bạn ấy sẽ lắng nghe.","Bàba māma shuōhuà de shíhou, tā huì tīng."],["他每天都去学校。","Bạn ấy đến trường mỗi ngày.","Tā měitiān dōu qù xuéxiào."],["他喜欢学习。","Bạn ấy thích học tập.","Tā xǐhuan xuéxí."],["回家以后，他先做作业。","Sau khi về nhà, bạn ấy làm bài tập trước.","Huí jiā yǐhòu, tā xiān zuò zuòyè."],["然后他帮妈妈做饭。","Sau đó bạn ấy giúp mẹ nấu ăn.","Ránhòu tā bāng māma zuòfàn."],["他也会帮爸爸买东西。","Bạn ấy cũng giúp bố mua đồ.","Tā yě huì bāng bàba mǎi dōngxi."],["爸爸妈妈累的时候，他会帮助他们。","Khi bố mẹ mệt, bạn ấy sẽ giúp bố mẹ.","Bàba māma lèi de shíhou, tā huì bāngzhù tāmen."],["他对朋友也很好。","Bạn ấy cũng đối xử tốt với bạn bè.","Tā duì péngyou yě hěn hǎo."],["他每天都很高兴。","Ngày nào bạn ấy cũng vui vẻ.","Tā měitiān dōu hěn gāoxìng."],["我也想做一个好孩子。","Tôi cũng muốn trở thành người con ngoan.","Wǒ yě xiǎng zuò yí ge hǎo háizi."]],"g":"E"},{"id":23,"q":"请说一下让你高兴的一件事。","qvi":"Kể về một việc khiến bạn vui","s":[["我很喜欢和家人一起吃饭。","Tôi rất thích ăn cơm cùng gia đình.","Wǒ hěn xǐhuan hé jiārén yìqǐ chīfàn."],["我爸爸妈妈都在家。","Bố mẹ tôi đều ở nhà.","Wǒ bàba māma dōu zài jiā."],["每天晚上，我们一起吃晚饭。","Tối nào chúng tôi cũng ăn cơm cùng nhau.","Měitiān wǎnshang, wǒmen yìqǐ chī wǎnfàn."],["妈妈做很多好吃的菜。","Mẹ nấu rất nhiều món ngon.","Māma zuò hěn duō hǎochī de cài."],["我最喜欢吃妈妈做的菜。","Tôi thích món mẹ nấu nhất.","Wǒ zuì xǐhuan chī māma zuò de cài."],["有时候，我也和妈妈一起做饭。","Đôi khi tôi cũng nấu ăn cùng mẹ.","Yǒu shíhou, wǒ yě hé māma yìqǐ zuòfàn."],["妈妈做菜，我帮妈妈。","Mẹ nấu ăn, tôi giúp mẹ.","Māma zuò cài, wǒ bāng māma."],["吃饭的时候，我们一起说话。","Khi ăn cơm, chúng tôi trò chuyện.","Chīfàn de shíhou, wǒmen yìqǐ shuōhuà."],["爸爸问我：“你今天学习汉语了吗？”","Bố hỏi: “Hôm nay con học tiếng Trung chưa?”","Bàba wèn wǒ: “Nǐ jīntiān xuéxí Hànyǔ le ma?”"],["我说：“学习了。”","Tôi đáp: “Con học rồi ạ.”","Wǒ shuō: “Xuéxí le.”"],["妈妈问我：“汉语难吗？”","Mẹ hỏi: “Tiếng Trung có khó không?”","Māma wèn wǒ: “Hànyǔ nán ma?”"],["我说：“有一点儿难。”","Tôi đáp: “Hơi khó ạ.”","Wǒ shuō: “Yǒu yìdiǎnr nán.”"],["爸爸妈妈听了都很高兴。","Bố mẹ nghe vậy đều rất vui.","Bàba māma tīng le dōu hěn gāoxìng."],["吃饭以后，我们一起看电视。","Sau khi ăn, chúng tôi cùng xem tivi.","Chīfàn yǐhòu, wǒmen yìqǐ kàn diànshì."],["我很喜欢和家人在一起。","Tôi rất thích ở bên gia đình.","Wǒ hěn xǐhuan hé jiārén zài yìqǐ."]],"g":"E"},{"id":24,"q":"你喜欢什么运动？为什么？","qvi":"Bạn thích môn thể thao nào? Vì sao?","s":[["我很喜欢运动。","Tôi rất thích thể thao.","Wǒ hěn xǐhuan yùndòng."],["我最喜欢踢足球。","Tôi thích đá bóng nhất.","Wǒ zuì xǐhuan tī zúqiú."],["我也喜欢跑步。","Tôi cũng thích chạy bộ.","Wǒ yě xǐhuan pǎobù."],["我每天早上六点起床。","Mỗi sáng tôi thức dậy lúc 6 giờ.","Wǒ měitiān zǎoshang liù diǎn qǐchuáng."],["我早上去跑步。","Buổi sáng tôi đi chạy bộ.","Wǒ zǎoshang qù pǎobù."],["跑步的时候，我喜欢听音乐。","Khi chạy bộ, tôi thích nghe nhạc.","Pǎobù de shíhou, wǒ xǐhuan tīng yīnyuè."],["下午六点，我和同学一起踢足球。","Lúc 6 giờ chiều, tôi cùng bạn học đá bóng.","Xiàwǔ liù diǎn, wǒ hé tóngxué yìqǐ tī zúqiú."],["我的同学也很喜欢足球。","Bạn học của tôi cũng rất thích bóng đá.","Wǒ de tóngxué yě hěn xǐhuan zúqiú."],["我们每个星期都一起踢足球。","Tuần nào chúng tôi cũng đá bóng cùng nhau.","Wǒmen měi ge xīngqī dōu yìqǐ tī zúqiú."],["踢足球的时候，我们都很高兴。","Khi đá bóng, chúng tôi đều rất vui.","Tī zúqiú de shíhou, wǒmen dōu hěn gāoxìng."],["踢足球以后，我有一点儿累。","Sau khi đá bóng, tôi hơi mệt.","Tī zúqiú yǐhòu, wǒ yǒu yìdiǎnr lèi."],["我回家喝水，也休息一下。","Tôi về nhà uống nước và nghỉ ngơi một chút.","Wǒ huí jiā hē shuǐ, yě xiūxi yíxià."],["我很喜欢和朋友一起踢足球。","Tôi rất thích đá bóng cùng bạn bè.","Wǒ hěn xǐhuan hé péngyou yìqǐ tī zúqiú."]],"g":"F"},{"id":25,"q":"妈妈有时候会让你帮她做什么？","qvi":"Mẹ thỉnh thoảng nhờ bạn làm việc gì?","s":[["我的妈妈每天都很忙。","Mẹ tôi ngày nào cũng rất bận.","Wǒ de māma měitiān dōu hěn máng."],["她每天在家做饭。","Mẹ nấu cơm ở nhà mỗi ngày.","Tā měitiān zài jiā zuòfàn."],["有时候妈妈会让我帮她。","Đôi khi mẹ nhờ tôi giúp.","Yǒu shíhou māma huì ràng wǒ bāng tā."],["妈妈说：“你来帮我，好吗？”","Mẹ nói: “Con đến giúp mẹ nhé?”","Māma shuō: “Nǐ lái bāng wǒ, hǎo ma?”"],["我说：“好，我来了。”","Tôi đáp: “Vâng, con đến đây.”","Wǒ shuō: “Hǎo, wǒ lái le.”"],["我先帮妈妈洗菜。","Trước tiên tôi giúp mẹ rửa rau.","Wǒ xiān bāng māma xǐ cài."],["然后我和妈妈一起做饭。","Sau đó tôi cùng mẹ nấu ăn.","Ránhòu wǒ hé māma yìqǐ zuòfàn."],["有时候我还帮妈妈买东西。","Đôi khi tôi còn giúp mẹ đi mua đồ.","Yǒu shíhou wǒ hái bāng māma mǎi dōngxi."],["吃饭以前，我拿碗和筷子。","Trước bữa ăn, tôi lấy bát và đũa.","Chīfàn yǐqián, wǒ ná wǎn hé kuàizi."],["吃饭以后，我洗碗。","Sau bữa ăn tôi rửa bát.","Chīfàn yǐhòu, wǒ xǐ wǎn."],["妈妈说：“谢谢你！”","Mẹ nói: “Cảm ơn con!”","Māma shuō: “Xièxie nǐ!”"],["我很高兴能帮助妈妈。","Tôi rất vui khi được giúp mẹ.","Wǒ hěn gāoxìng néng bāngzhù māma."]],"g":"F"},{"id":26,"q":"你每天锻炼身体吗？","qvi":"Bạn có tập thể dục mỗi ngày không?","s":[["我很喜欢运动。","Tôi rất thích thể thao.","Wǒ hěn xǐhuan yùndòng."],["我每天早上六点起床。","Mỗi sáng tôi thức dậy lúc 6 giờ.","Wǒ měitiān zǎoshang liù diǎn qǐchuáng."],["我先喝一点儿水。","Đầu tiên tôi uống một ít nước.","Wǒ xiān hē yìdiǎnr shuǐ."],["然后我去跑步。","Sau đó tôi đi chạy bộ.","Ránhòu wǒ qù pǎobù."],["我喜欢在早上跑步。","Tôi thích chạy bộ buổi sáng.","Wǒ xǐhuan zài zǎoshang pǎobù."],["跑步的时候，我听音乐。","Khi chạy bộ tôi nghe nhạc.","Pǎobù de shíhou, wǒ tīng yīnyuè."],["跑步以后，我回家吃早饭。","Sau khi chạy bộ tôi về nhà ăn sáng.","Pǎobù yǐhòu, wǒ huí jiā chī zǎofàn."],["下午六点，我有时候踢足球。","Lúc 6 giờ chiều, đôi khi tôi đá bóng.","Xiàwǔ liù diǎn, wǒ yǒu shíhou tī zúqiú."],["我和同学一起踢足球。","Tôi đá bóng cùng bạn học.","Wǒ hé tóngxué yìqǐ tī zúqiú."],["我觉得运动对身体很好。","Tôi nghĩ vận động rất tốt cho sức khỏe.","Wǒ juéde yùndòng duì shēntǐ hěn hǎo."],["运动以后，我有一点儿累。","Sau vận động, tôi hơi mệt.","Yùndòng yǐhòu, wǒ yǒu yìdiǎnr lèi."],["但是我很高兴。","Nhưng tôi rất vui.","Dànshì wǒ hěn gāoxìng."]],"g":"F"},{"id":27,"q":"你觉得早睡早起对身体好吗？为什么？","qvi":"Ngủ sớm dậy sớm có tốt cho sức khỏe không?","s":[["我觉得早睡早起很好。","Tôi thấy ngủ sớm, dậy sớm rất tốt.","Wǒ juéde zǎo shuì zǎo qǐ hěn hǎo."],["我每天晚上十点睡觉。","Mỗi tối tôi đi ngủ lúc 10 giờ.","Wǒ měitiān wǎnshang shí diǎn shuìjiào."],["早上六点，我起床。","Sáu giờ sáng tôi thức dậy.","Zǎoshang liù diǎn, wǒ qǐchuáng."],["我先喝一点儿水。","Trước tiên tôi uống chút nước.","Wǒ xiān hē yìdiǎnr shuǐ."],["然后我去跑步。","Sau đó tôi đi chạy bộ.","Ránhòu wǒ qù pǎobù."],["跑步以后，我吃早饭。","Sau khi chạy bộ tôi ăn sáng.","Pǎobù yǐhòu, wǒ chī zǎofàn."],["八点我去学校学习汉语。","Lúc 8 giờ tôi đến trường học tiếng Trung.","Bā diǎn wǒ qù xuéxiào xuéxí Hànyǔ."],["早上我不太累。","Buổi sáng tôi không quá mệt.","Zǎoshang wǒ bú tài lèi."],["我喜欢早上学习。","Tôi thích học buổi sáng.","Wǒ xǐhuan zǎoshang xuéxí."],["晚上我不看很多电影。","Buổi tối tôi không xem nhiều phim.","Wǎnshang wǒ bú kàn hěn duō diànyǐng."],["我早点儿睡觉。","Tôi đi ngủ sớm một chút.","Wǒ zǎo diǎnr shuìjiào."],["我觉得这样对身体很好。","Tôi nghĩ như thế rất tốt cho sức khỏe.","Wǒ juéde zhèyàng duì shēntǐ hěn hǎo."]],"g":"F"},{"id":28,"q":"给你三天时间，你会做什么？","qvi":"Nếu có ba ngày, bạn sẽ làm gì?","s":[["我有三天时间。","Tôi có ba ngày rảnh.","Wǒ yǒu sān tiān shíjiān."],["我想和家人一起玩。","Tôi muốn đi chơi cùng gia đình.","Wǒ xiǎng hé jiārén yìqǐ wán."],["第一天，我在家休息。","Ngày thứ nhất tôi nghỉ ở nhà.","Dì yī tiān, wǒ zài jiā xiūxi."],["我和妈妈一起做饭。","Tôi cùng mẹ nấu ăn.","Wǒ hé māma yìqǐ zuòfàn."],["晚上我们一起看电视。","Buổi tối chúng tôi cùng xem tivi.","Wǎnshang wǒmen yìqǐ kàn diànshì."],["第二天，我想去海边。","Ngày thứ hai tôi muốn đi biển.","Dì èr tiān, wǒ xiǎng qù hǎibiān."],["我想和朋友一起去。","Tôi muốn đi cùng bạn bè.","Wǒ xiǎng hé péngyou yìqǐ qù."],["我们可以在海边玩。","Chúng tôi có thể chơi ở bãi biển.","Wǒmen kěyǐ zài hǎibiān wán."],["第三天，我去踢足球。","Ngày thứ ba tôi đi đá bóng.","Dì sān tiān, wǒ qù tī zúqiú."],["踢足球以后，我去喝咖啡。","Sau khi đá bóng, tôi đi uống cà phê.","Tī zúqiú yǐhòu, wǒ qù hē kāfēi."],["晚上我在家学习一点儿汉语。","Buổi tối tôi học một chút tiếng Trung ở nhà.","Wǎnshang wǒ zài jiā xuéxí yìdiǎnr Hànyǔ."],["我觉得这三天很好。","Tôi nghĩ ba ngày này thật tuyệt.","Wǒ juéde zhè sān tiān hěn hǎo."]],"g":"G"},{"id":29,"q":"你以后想做什么工作？为什么？","qvi":"Sau này bạn muốn làm công việc gì? Vì sao?","s":[["我以前在莫斯科学习电脑。","Trước đây tôi học về máy tính tại Moscow.","Wǒ yǐqián zài Mòsīkē xuéxí diànnǎo."],["现在我在学习汉语。","Bây giờ tôi học tiếng Trung.","Xiànzài wǒ zài xuéxí Hànyǔ."],["我很喜欢电脑，也喜欢汉语。","Tôi rất thích máy tính và tiếng Trung.","Wǒ hěn xǐhuan diànnǎo, yě xǐhuan Hànyǔ."],["以后我想在公司工作。","Sau này tôi muốn làm việc tại công ty.","Yǐhòu wǒ xiǎng zài gōngsī gōngzuò."],["我想去FIT公司工作。","Tôi muốn làm việc tại FIT.","Wǒ xiǎng qù FIT gōngsī gōngzuò."],["我家离公司不太远。","Nhà tôi không cách công ty quá xa.","Wǒ jiā lí gōngsī bú tài yuǎn."],["我想每天去上班。","Tôi muốn đi làm mỗi ngày.","Wǒ xiǎng měitiān qù shàngbān."],["我想和同事一起工作。","Tôi muốn làm việc cùng đồng nghiệp.","Wǒ xiǎng hé tóngshì yìqǐ gōngzuò."],["我也想在公司说汉语。","Tôi cũng muốn dùng tiếng Trung trong công ty.","Wǒ yě xiǎng zài gōngsī shuō Hànyǔ."],["我想认识更多朋友。","Tôi muốn quen thêm nhiều người bạn.","Wǒ xiǎng rènshi gèng duō péngyou."],["我会好好学习汉语。","Tôi sẽ học tiếng Trung thật tốt.","Wǒ huì hǎohǎo xuéxí Hànyǔ."],["我也会好好工作。","Tôi cũng sẽ làm việc thật tốt.","Wǒ yě huì hǎohǎo gōngzuò."]],"g":"G"},{"id":30,"q":"你喜欢看书吗？你喜欢看什么书？","qvi":"Bạn thích đọc sách không? Thích sách gì?","s":[["我很喜欢看书。","Tôi rất thích đọc sách.","Wǒ hěn xǐhuan kàn shū."],["我家有很多书。","Nhà tôi có nhiều sách.","Wǒ jiā yǒu hěn duō shū."],["我现在在学习汉语。","Hiện tại tôi học tiếng Trung.","Wǒ xiànzài zài xuéxí Hànyǔ."],["所以我喜欢看汉语书。","Vì vậy tôi thích đọc sách tiếng Trung.","Suǒyǐ wǒ xǐhuan kàn Hànyǔ shū."],["我每天晚上在家看书。","Mỗi tối tôi đọc sách ở nhà.","Wǒ měitiān wǎnshang zài jiā kàn shū."],["我先看汉字。","Đầu tiên tôi nhìn chữ Hán.","Wǒ xiān kàn Hànzì."],["然后我读一读。","Sau đó tôi đọc một lượt.","Ránhòu wǒ dú yi dú."],["有不认识的字，我问老师。","Có chữ không biết, tôi hỏi giáo viên.","Yǒu bú rènshi de zì, wǒ wèn lǎoshī."],["有时候我也看电脑书。","Đôi khi tôi cũng đọc sách máy tính.","Yǒu shíhou wǒ yě kàn diànnǎo shū."],["我觉得看书很好。","Tôi thấy đọc sách rất tốt.","Wǒ juéde kàn shū hěn hǎo."],["看书的时候，我不看手机。","Khi đọc sách tôi không nhìn điện thoại.","Kàn shū de shíhou, wǒ bú kàn shǒujī."],["我想每天都看一点儿书。","Tôi muốn đọc một chút sách mỗi ngày.","Wǒ xiǎng měitiān dōu kàn yìdiǎnr shū."]],"g":"H"},{"id":31,"q":"你最喜欢的颜色是什么？","qvi":"Màu sắc bạn thích nhất là gì?","s":[["我很喜欢白色。","Tôi rất thích màu trắng.","Wǒ hěn xǐhuan báisè."],["白色是我最喜欢的颜色。","Màu trắng là màu tôi yêu thích nhất.","Báisè shì wǒ zuì xǐhuan de yánsè."],["我有很多白色的衣服。","Tôi có nhiều quần áo màu trắng.","Wǒ yǒu hěn duō báisè de yīfu."],["我有三件白色的衣服。","Tôi có ba chiếc áo màu trắng.","Wǒ yǒu sān jiàn báisè de yīfu."],["我也有一件黑色的衣服。","Tôi cũng có một chiếc áo màu đen.","Wǒ yě yǒu yí jiàn hēisè de yīfu."],["但是我最喜欢白色的。","Nhưng tôi thích màu trắng nhất.","Dànshì wǒ zuì xǐhuan báisè de."],["星期天我喜欢穿白色的衣服。","Chủ nhật tôi thích mặc áo trắng.","Xīngqītiān wǒ xǐhuan chuān báisè de yīfu."],["我觉得白色很好看。","Tôi thấy màu trắng rất đẹp.","Wǒ juéde báisè hěn hǎokàn."],["我也喜欢白色的车。","Tôi cũng thích xe màu trắng.","Wǒ yě xǐhuan báisè de chē."],["以后我想买一辆白色的车。","Sau này tôi muốn mua một chiếc xe màu trắng.","Yǐhòu wǒ xiǎng mǎi yí liàng báisè de chē."],["我的朋友喜欢黑色。","Bạn tôi thích màu đen.","Wǒ de péngyou xǐhuan hēisè."],["我们喜欢的颜色不一样。","Màu chúng tôi thích không giống nhau.","Wǒmen xǐhuan de yánsè bù yíyàng."]],"g":"H"},{"id":32,"q":"你觉得快乐的生活是什么样的？","qvi":"Theo bạn, cuộc sống vui vẻ là như thế nào?","s":[["我想每天都很高兴。","Tôi muốn mỗi ngày đều vui vẻ.","Wǒ xiǎng měitiān dōu hěn gāoxìng."],["我喜欢和家人在一起。","Tôi thích ở bên gia đình.","Wǒ xǐhuan hé jiārén zài yìqǐ."],["每天晚上，我们一起吃饭。","Mỗi tối chúng tôi ăn cơm cùng nhau.","Měitiān wǎnshang, wǒmen yìqǐ chīfàn."],["吃饭的时候，我们一起说话。","Khi ăn, chúng tôi cùng nói chuyện.","Chīfàn de shíhou, wǒmen yìqǐ shuōhuà."],["爸爸妈妈都很高兴。","Bố mẹ đều rất vui.","Bàba māma dōu hěn gāoxìng."],["我也喜欢和朋友踢足球。","Tôi cũng thích đá bóng cùng bạn bè.","Wǒ yě xǐhuan hé péngyou tī zúqiú."],["踢足球以后，我有一点儿累。","Sau khi đá bóng tôi hơi mệt.","Tī zúqiú yǐhòu, wǒ yǒu yìdiǎnr lèi."],["但是我很开心。","Nhưng tôi rất vui.","Dànshì wǒ hěn kāixīn."],["我每天还学习汉语。","Mỗi ngày tôi còn học tiếng Trung.","Wǒ měitiān hái xuéxí Hànyǔ."],["我想以后找一个好工作。","Tôi muốn sau này tìm một công việc tốt.","Wǒ xiǎng yǐhòu zhǎo yí ge hǎo gōngzuò."],["有时间的时候，我想去旅游。","Khi có thời gian tôi muốn đi du lịch.","Yǒu shíjiān de shíhou, wǒ xiǎng qù lǚyóu."],["我想去北京，也想去海边。","Tôi muốn đi Bắc Kinh và đi biển.","Wǒ xiǎng qù Běijīng, yě xiǎng qù hǎibiān."],["我觉得这样就是快乐的生活。","Tôi nghĩ cuộc sống như thế chính là hạnh phúc.","Wǒ juéde zhèyàng jiù shì kuàilè de shēnghuó."]],"g":"H"}];
